fn = '''

def cascade_diagonal(grid):
    """The shapes (connected same-color components), ordered left to right, redrawn as a diagonal cascade from the top-left: each shape's top-left cell is the previous shape's bottom-right cell."""
    h, w = len(grid), len(grid[0])
    seen = [[False]*w for _ in range(h)]
    shapes = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                stack = [(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    r,c = stack.pop(); cells.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc = r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and grid[nr][nc]==grid[i][j] and not seen[nr][nc]:
                            seen[nr][nc]=True; stack.append((nr,nc))
                rs=[r for r,_ in cells]; cs=[c for _,c in cells]
                r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
                pat = [[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
                shapes.append((c0, pat))
    shapes.sort()
    out = [[0]*w for _ in range(h)]
    top, left = 0, 0
    for _, pat in shapes:
        ph, pw = len(pat), len(pat[0])
        for r in range(ph):
            for c in range(pw):
                if pat[r][c]:
                    rr, cc = top+r, left+c
                    if 0<=rr<h and 0<=cc<w: out[rr][cc] = pat[r][c]
        top, left = top+ph-1, left+pw-1
    return out
'''
